class Grid {
	constructor(w, h) {
		this.w = w;
		this.h = h;
		this.grid = [];
    for (let y = 0; y < this.h; y++) {
			this.grid[y] = [];
			for (let x = 0; x < this.w; x++)
				this.grid[y][x] = 0;
		}

	}

	get(x, y) {
		x = constrain(x, 0, this.w);
		y = constrain(y, 0, this.h);
		return this.grid[y][x]
	}

	clear(noice = false) {
		for (let y = 0; y < this.h; y++)
			for (let x = 0; x < this.w; x++) 
				this.grid[y][x] = noice ? noise(x*0.0082,y*0.0095,frameCount*0.0073) : 0.151;
	}

	circle(xo, yo, rad) {
		const u = TWO_PI * rad;
		const da = TWO_PI / u;
		for (let a = 0; a < TWO_PI; a += da) {
			const xv = cos(a) * rad + xo;
			const yv = sin(a) * rad + yo;
			const x = round(xv);
			const y = round(yv);
			if (x >= 0 && y >= 0 && x < this.w && y < this.h) {
				// fraction, 0.5 = max
				const xf = fract(xv);
				const yf = fract(yv);
				// intensity
				const xi = xf - 0.5;
				const yi = yf - 0.5;
				this.grid[y][x] += abs(xi) + abs(yi);
				if (x > 0 && xi < 0) this.grid[y][x-1] += abs(xi - 0.5);
				if (x < this.w - 1 && xi > 0) this.grid[y][x+1] += abs(xi - 0.5);
				if (y > 0 && yi < 0) this.grid[y-1][x] += abs(yi - 0.5);
				if (y < this.h - 1 && yi > 0) this.grid[y+1][x] += abs(yi - 0.5);
			}
		}
	}
}
